import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import {
  SKELETON_DEFAULT_ARIA_LABEL,
  SKELETON_DEFAULT_HEIGHT,
  SKELETON_DEFAULT_WIDTH,
  SKELETON_IMAGE_ALT,
  SKELETON_IMAGE_PLACEHOLDER,
} from './SkeletonLoader.constants';
import {
  StyledSkeletonImage,
  StyledSkeletonLoader,
} from './SkeletonLoader.styles';
import type { SkeletonLoaderProps } from './SkeletonLoader.types';

export const SkeletonLoader = React.forwardRef<
  HTMLDivElement,
  SkeletonLoaderProps
>(
  (
    {
      height = SKELETON_DEFAULT_HEIGHT,
      width = SKELETON_DEFAULT_WIDTH,
      variant = 'body',
      imageShape = 'rectangle',
      className,
      tabIndex = -1,
      ...props
    },
    forwardedRef,
  ) => (
    <StyledSkeletonLoader
      {...omitTransientProps(props)}
      ref={forwardedRef}
      className={className}
      role="status"
      aria-busy="true"
      aria-label={props['aria-label'] ?? SKELETON_DEFAULT_ARIA_LABEL}
      tabIndex={tabIndex}
      $imageShape={imageShape}
      $variant={variant}
      style={{ height, width }}
    >
      {variant === 'image' ? (
        <StyledSkeletonImage
          alt={SKELETON_IMAGE_ALT}
          src={SKELETON_IMAGE_PLACEHOLDER}
        />
      ) : null}
    </StyledSkeletonLoader>
  ),
);

SkeletonLoader.displayName = 'SkeletonLoader';
